	/**
	 * 获取正签发起时可以选择的C报价信息
	 * 包含设计师正签时做的C报价以及家居顾问做的协同C报价
	 * @param projectOrderId
	 * @return
	 */
	@Deprecated
	public List<ContractFormalQuotationDTO.FormalSealInfo> getFormalQuotationList(String projectOrderId){
		//开关处理
		Boolean openFormalMultiple = contractApolloConfig.getOpenFormalMultiple();
		if (!openFormalMultiple) {
			LOGGER.info("开关关闭，返回空列表 projectOrderId:{}", projectOrderId);
			return new ArrayList<>();
		}

		if (!commonBusinessService.isProcessV25New(projectOrderId)) {
			return new ArrayList<>();
		}
		//获取正签报价
		ContractSourceDataBO contractSourceDataBO = homeOrderDataConversionService.contractSourceDateNoThrow(projectOrderId,null);
		PlanAllDTO planAllDTO = contractSourceDataBO.getPlanAllDTO();
		if (planAllDTO == null) {
			return new ArrayList<>();
		}
		Byte businessType = commonBusinessService.getBusinessType(projectOrderId);

		//根据协同报价单查询组合单信息
		List<CompositInfoWithBillCode> compositInfoWithBillCodes = contractOrderCenterRpc.queryOrderByHomeOrderNo(projectOrderId);
		//过滤出非取消的
		compositInfoWithBillCodes = compositInfoWithBillCodes.stream().filter(item -> !CompositOrderStateEnum.CANCELED.getValue().equals(item.getOrderStatus())).collect(Collectors.toList());
		//获取正签C报价单信息
		List<SignOrderInfo> formalQuotationInfoList = getFormalQuotationInfoList(contractSourceDataBO, compositInfoWithBillCodes, projectOrderId,businessType);
		//获取协同报价单信息,(整装)过滤出于正签分公司不同的协同报价单信息，相同的主体已经合并到正签C报价中了
		List<SignOrderInfo> cooperQuoteInfoList = getCooperQuoteInfoList(projectOrderId, compositInfoWithBillCodes,businessType);
		if (CollectionUtils.isEmpty(formalQuotationInfoList) && CollectionUtils.isEmpty(cooperQuoteInfoList)) {
			return Collections.emptyList();
		}
		List<ContractFormalQuotationDTO.FormalSealInfo> formalSealInfoList = new ArrayList<>();

		List<SignOrderInfo> merageQuoteInfoList = new ArrayList<>();
		merageQuoteInfoList.addAll(formalQuotationInfoList);
		merageQuoteInfoList.addAll(cooperQuoteInfoList);

		//构建报价单信息
		if(CollectionUtils.isNotEmpty(merageQuoteInfoList)){
			Map<String, List<SignOrderInfo>> groupedByCompanyCode = merageQuoteInfoList.stream()
				.collect(Collectors.groupingBy(SignOrderInfo::getCompanyCode));
			groupedByCompanyCode.forEach((companyCode, signOrderInfos) -> {
				//分公司名称
				String companyName = signOrderInfos.get(0).getCompanyName();
				ContractFormalQuotationDTO.FormalSealInfo formalSealInfo = ContractFormalQuotationDTO.FormalSealInfo.builder()
					.companyName(companyName)
					.companyCode(companyCode)
					.signOrderInfoList(signOrderInfos)
					.build();
				formalSealInfoList.add(formalSealInfo);
			});
		}
		return formalSealInfoList;
	}

	/**
	 * 获取正签发起时可以选择的C报价信息
	 * 包含设计师正签时做的C报价以及家居顾问做的协同C报价
	 * @param projectOrderId
	 * @return
	 */
	public List<SignableOrderInfoGroup> getFormalQuotationListV2(String projectOrderId){
		if (!commonBusinessService.isProcessV25New(projectOrderId)) {
			return Collections.emptyList();
		}
		// 获取可签约的报价单据
		List<SignableOrderInfo> formalQuotationInfoListV2 = contractSigningSourceRouter.route(BindTypeEnum.BILL_CODE.getCode()).buildSignableOrderInfos(projectOrderId);


		// 正签场景，如果没有报价单据，则直接返回空即可；如果是团装 2.5，则继续往下走，查询可签约的 S 单
		if (CollectionUtils.isEmpty(formalQuotationInfoListV2) && !commonBusinessService.isPROCESS_V2_5_GROUP(projectOrderId)) {
			return Collections.emptyList();
		}

		// 获取可签约的 S 单据
		List<SignableOrderInfo> signableOrderInfos = contractSigningSourceRouter.route(BindTypeEnum.SUB_ORDER.getCode()).buildSignableOrderInfos(projectOrderId);

		// 团装 2.5 正签弹窗默认勾选所有 S 单
		if (commonBusinessService.isPROCESS_V2_5_GROUP(projectOrderId)) {
			signableOrderInfos.forEach(item -> item.setMustSelect(true));
		}

		List<SignableOrderInfo> totalSignableOrderInfos = new ArrayList<>();
		totalSignableOrderInfos.addAll(formalQuotationInfoListV2);
		totalSignableOrderInfos.addAll(signableOrderInfos);

		return SignableOrderInfoGroup.buildGroup(totalSignableOrderInfos);
	}

	/**
	 * 获取基础报价内的 C 报价信息
	 */
	@Deprecated
	public List<SignOrderInfo> getFormalQuotationInfoList(ContractSourceDataBO contractSourceDataBO,List<CompositInfoWithBillCode> compositInfoWithBillCodes,String projectOrderId,Byte businessType) {
		PlanAllDTO planAllDTO = contractSourceDataBO.getPlanAllDTO();
		if (BusinessTypeEnum.REFORM_ALL.getCode().equals(businessType) && CollectionUtils.isNotEmpty(contractSourceDataBO.getPersonalContractDataList())
			|| BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType)
			|| (BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType) && CollectionUtils.isNotEmpty(contractSourceDataBO.getPersonalContractDataList()))
		) {
			List<ContractSourceDataBO.PersonalContractData> personalContractDataList = contractSourceDataBO.getPersonalContractDataList();
			if (CollectionUtils.isEmpty(personalContractDataList)) {
				return Collections.emptyList();
			}
			if (!contractDependentDataService.groupPersonalForFormal(projectOrderId) && BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType)) {
				return Collections.emptyList();
			}
			List<SignOrderInfo> signOrderInfoList = new ArrayList<>();
			for (ContractSourceDataBO.PersonalContractData personalContractData : personalContractDataList) {
				SignOrderInfo signOrderInfo = SignOrderInfo.builder()
					.companyName(personalContractData.getOrganizationName())
					.companyCode(personalContractData.getOrganizationCode())
					.mustSelect(true)
					.billCodeList(Collections.singletonList(personalContractData.getBillCode()))
					.billCode(personalContractData.getBillCode())
					.goodsInfo("")
					.orderAmount(personalContractData.getPersonalContractPrice())
					.orderCreateTime(personalContractData.getCreateTime())
					.build();
				signOrderInfoList.add(signOrderInfo);
			}
			return signOrderInfoList;
		}

		PlanAttachmentDTO attachmentDTO = planAllDTO.getPlanAttachmentList().stream().filter(planAttachmentDTO -> planAttachmentDTO.getFileType().equals(PlanAttachment.套外个性化报价单))
			.findFirst()
			.orElse(null);
		//如果没有套外个性化报价单，则不需要组装C报价单信息
		if (ObjectUtil.isEmpty(attachmentDTO)) {
			return Collections.emptyList();
		}
		//协同报价单号列表
		List<String> cooperBillCodes = planAllDTO.getCooperBillCodes();
			//如果合并到正签的协同C报价已发起过C合同，则不需要组装C报价单信息
			List<ContractQuotationRelation> relationListByBillCodeList = quotationRelationCommonService.getRelationListByBillCodeList(cooperBillCodes);
			List<String> relationContractCodes = new ArrayList<>();
			Contract contractInfo = contractService.getContractInfo(projectOrderId, ContractTypeEnum.PACKAGE_FORMAL.getCode());
			if (contractInfo != null) {
				List<ContractRelation> relationList = contractRelationService.getRelationList(contractInfo.getContractCode());
				relationContractCodes = relationList.stream().map(ContractRelation::getRelateContractCode).collect(Collectors.toList());
			}
			for (ContractQuotationRelation contractQuotationRelation : relationListByBillCodeList) {
				Contract contract = contractService.getByContractCode(contractQuotationRelation.getContractCode());
				if (contract != null && !relationContractCodes.contains(contract.getContractCode()) && ContractStatusEnum.validStatusWithoutDraft.contains(contract.getStatus())) {
					LOGGER.info("合并到正签报价的协同C报价单已发起过个性化合同, billCode:{}, contractCode:{}, status:{}",
						contractQuotationRelation.getBillCode(), contractQuotationRelation.getContractCode(), contract.getStatus());
					return Collections.emptyList();
				}
			}
		//正签报价单号
		String billCode = planAllDTO.getBudgetBillDTO().getBillCode();
		//正签报价单+协同报价单号列表
		List<String> billCodeList = new ArrayList<>();
		billCodeList.add(billCode);
		String goodsInfo = "";
		if (CollectionUtils.isNotEmpty(cooperBillCodes)) {
			goodsInfo = compositInfoWithBillCodes.stream().filter(item -> cooperBillCodes.contains(item.getBillCode())).map(CompositInfoWithBillCode::getGoodsInfo).collect(Collectors.joining(","));
		}
		SignOrderInfo signOrderInfo = SignOrderInfo.builder()
			.companyName(planAllDTO.getPlanInfo().getOrganizationName())
			.companyCode(planAllDTO.getPlanInfo().getOrganizationCode())
			.mustSelect(true)
			.billCodeList(billCodeList)
			.billCode(billCode)
			.goodsInfo(goodsInfo)
			.orderAmount(planAllDTO.getPlanInfo().getPersonalTotalPrice())
			.orderCreateTime(planAllDTO.getBudgetBillDTO().getCtimeStr())
			.build();
		return Collections.singletonList(signOrderInfo);
	}


	/**
	 * 获取协同报价单信息列表
	 *
	 * @param projectOrderId
	 * @return
	 */
	public List<SignOrderInfo> getCooperQuoteInfoList(String projectOrderId, List<CompositInfoWithBillCode> compositInfoWithBillCodes, Byte businessType) {
		// 根据协同报价单查询组合单信息
		if (ObjectUtil.isEmpty(compositInfoWithBillCodes) || BusinessTypeEnum.GROUP_DECORATE.getCode().equals(businessType)) {
			return Collections.emptyList();
		}
		List<String> notSupportSignBillCodeList = getNotSupportSignBillCodeList(projectOrderId);
		List<String> companyCodeList = new ArrayList<>();
		List<String> billCodeList = new ArrayList<>();
		// 获取 CT 单的报价单号 + 主体
		for (CompositInfoWithBillCode compositInfoWithBillCode : compositInfoWithBillCodes) {
			billCodeList.add(compositInfoWithBillCode.getBillCode());
			companyCodeList.add(compositInfoWithBillCode.getMdmCode());
		}
		List<ContractQuotationRelation> relationListByBillCodeList = quotationRelationCommonService.getRelationListByBillCodeList(billCodeList);
		// 查询已绑定合同的【报价单号+主体】
		List<String> allContractRelationList = relationListByBillCodeList.stream().map(item -> item.getBillCode() + "_" + item.getCompanyCode()).collect(Collectors.toList());
		//批量查询分公司信息
		Map<String, MdmDTO> mdmDTOMap = mdmRpc.obtainMdmMapByMdmCodes(companyCodeList);
		List<SignOrderInfo> signOrderInfoList = new ArrayList<>();
		// 正签合并发起合同所关联的报价单号
		List<String> formalRelationBillCodeList = new ArrayList<>();
		Contract formalContractInfo = contractService.getContractInfo(projectOrderId, ContractTypeEnum.PACKAGE_FORMAL.getCode());
		if (formalContractInfo != null) {
			List<ContractRelation> relationList = contractRelationService.getRelationList(formalContractInfo.getContractCode());
			List<String> relationContractCodeList = relationList.stream().map(ContractRelation::getRelateContractCode).collect(Collectors.toList());
			if (CollectionUtils.isNotEmpty(relationContractCodeList)){
				List<ContractQuotationRelation> contractQuotationRelationList = contractQuotationRelationService.getByContractCodesAndStatus(relationContractCodeList, RelationStatusEnum.RELATED.getCode());
				formalRelationBillCodeList = contractQuotationRelationList.stream().map(item -> item.getBillCode() + "_" + item.getCompanyCode()).collect(Collectors.toList());
			}
		}
		// 基于 CT 单号进行筛选
		for (CompositInfoWithBillCode compositInfoWithBillCode : compositInfoWithBillCodes) {
			// notSupportSignBillCodeList：不支持签约的协同报价单
			// formalRelationBillCodeList：正签合并发起的合同已经关联过的报价单号
			// allContractRelationList：已经关联过合同的报价单
			if (CompositOrderStateEnum.CANCELED.getValue().equals(compositInfoWithBillCode.getOrderStatus())
				|| notSupportSignBillCodeList.contains(compositInfoWithBillCode.getBillCode())
				// 报价单如果是正签合并发起的，则可以进行选择；报价单如果不是正签合并的&已经与其他合同关联（报价单不是正签合并发起的），则不能选择
				|| (!formalRelationBillCodeList.contains(compositInfoWithBillCode.getBillCode() + "_" + compositInfoWithBillCode.getMdmCode()) && allContractRelationList.contains(compositInfoWithBillCode.getBillCode() + "_" + compositInfoWithBillCode.getMdmCode()))) {
				continue;
			}
			//获取分公司名称
			MdmDTO mdmDTO = mdmDTOMap.get(compositInfoWithBillCode.getMdmCode());
			SignOrderInfo signOrderInfo = SignOrderInfo.builder()
				.companyName(ObjectUtil.isEmpty(mdmDTO) ? "" : mdmDTO.getCompanyName())
				.companyCode(compositInfoWithBillCode.getMdmCode())
				.mustSelect(false)
				.billCodeList(Collections.singletonList(compositInfoWithBillCode.getBillCode()))
				.billCode(compositInfoWithBillCode.getBillCode())
				.goodsInfo(compositInfoWithBillCode.getGoodsInfo())
				.orderAmount(compositInfoWithBillCode.getCustomerDueAmount())
				.orderCreateTime(DateUtils.getFormatDateStr(compositInfoWithBillCode.getOrderCreateTime(), "yyyy-MM-dd HH:mm:ss"))
				.build();
			signOrderInfoList.add(signOrderInfo);
		}
		return signOrderInfoList;
	}



	/**
	 * 获取不支持签约的协同报价单列表
	 * @param projectOrderId
	 * @return
	 */
	public List<String> getNotSupportSignBillCodeList(String projectOrderId){
		BudgetParams.QueryBillsCondition queryBillsCondition = BudgetParams.QueryBillsCondition.builder()
			.projectOrderId(projectOrderId)
			.billTypeList(Arrays.asList(GeneralBillTypeEnum.BUDGET_COOPER.getCode(), GeneralBillTypeEnum.CHANGE_COOPER.getCode()))
			.billStatusList(Arrays.asList(GeneralBillStatusEnum.FORMALISED.getCode(), GeneralBillStatusEnum.SIGNED.getCode(), GeneralBillStatusEnum.SUBMITTED.getCode()))
			.build();
		List<com.ke.utopia.atom.api.budget.dto.BudgetBillDTO.BillDTO> billDTOS = atomBudgetRpc.queryBillsByCondition(queryBillsCondition);
		if (CollectionUtils.isEmpty(billDTOS)) {
			return Collections.emptyList();
		}
		//变更协同报价单的分公司
		List<String> changeBillCodeList = new ArrayList<>();
		for (com.ke.utopia.atom.api.budget.dto.BudgetBillDTO.BillDTO billDTO : billDTOS) {
			if (GeneralBillTypeEnum.CHANGE_COOPER.getCode().equals(billDTO.getBillType())) {
				changeBillCodeList.add(billDTO.getBillCode());
			}
		}
		//不可签约的报价单
		List<String> notSupportSignBillCodeList = new ArrayList<>();
		//查询变更报价单的信息
		HashMap<String, ChangeDTO.ChangeBillDTO> changeBillDTOHashMap = atomBudgetRpc.queryChangeByQuotationBillCode(changeBillCodeList);
		for (ChangeDTO.ChangeBillDTO changeBillDTO : changeBillDTOHashMap.values()) {
			//筛选出不允许签约的变更单状态:待签约-已完成允许签约
			if (!ChangeBusinessStatusEnum.WAIT_SIGN.getCode().equals(changeBillDTO.getChangeProcessStatus())
				&& !ChangeBusinessStatusEnum.FINISHED.getCode().equals(changeBillDTO.getChangeProcessStatus())) {
				LOGGER.info("变更报价单状态不允许签约 projectOrderId:{},changeBillDTO:{}", projectOrderId, JSON.toJSONString(changeBillDTO));
				notSupportSignBillCodeList.add(changeBillDTO.getRelationBillCode());
			}
		}
		return notSupportSignBillCodeList;
	}










