@Slf4j
@Service
public class PersonalRelationHandlerImpl implements PersonalRelationHandler {

	private static final Long DEFAULT_OPERATOR_UCID = 100000000000000L;

	/**
	 * 合同撤回操作类型
	 */
	private enum ContractRevocationAction {
		/** 作废合同 */
		CANCEL_CONTRACT,
		/** 解除关联并撤回合同 */
		UNBIND_AND_UNDO,
		/** 跳过处理 */
		SKIP
	}

	@Resource
	private ContractService contractService;

	@Resource
	private CommonContractService commonContractService;

	@Resource
	private QuotationRelationCommonService quotationRelationCommonService;

	@Resource
	private ContractQuotationRelationService contractQuotationRelationService;

	@Resource
	private HomeAndPcCommonService homeAndPcCommonService;

	@Resource
	private ContractRelationService contractRelationService;

	@Resource
	private ContractFieldHandler contractFieldHandler;

	@Resource
	private SubOrderFeignService subOrderFeignService;

	@Resource
	private LockService lockService;

	@Resource
	private ContractBindLogService contractBindLogService;

	@Override
	public void revokeCooperQuotation(String projectOrderId, String cooperBillCode, Long operatorUcid) {
		// 撤回协同报价与协同报价换绑至 S 加锁互斥
		try {
			lockService.lockElseThrow(LockService.CONTRACT_RELATION_BILL_CODE + cooperBillCode, () -> {
				// 获取直接绑定该报价单的合同
				List<Contract> relatedContracts = quotationRelationCommonService.getContractByBillCode(cooperBillCode);

				if (CollectionUtil.isNotEmpty(relatedContracts)) {
					// 协同报价单与合同绑定，直接处理
					for (Contract contract : relatedContracts) {
						unbindCooperQuotationFromContract(contract, cooperBillCode, projectOrderId, operatorUcid);
					}
				} else {
					// 协同报价单未绑定合同，则S单与合同绑定，通过S单处理
					unbindSubOrderFromContract(projectOrderId, cooperBillCode, operatorUcid);
				}
				return null;
			}, 10000);
		} catch (Exception e) {
			throw new NrsBusinessException(String.format("协同报价单撤回失败, projectOrderId: %s, cooperBillCode: %s", projectOrderId, cooperBillCode));
		}

	}


	/**
	 * 获取协同报价单对应的所有 S 单号
	 */
	private List<String> getSubOrderNosByBillCode(String projectOrderId, String billCode) {
		return subOrderFeignService.queryAllStatusBaseInfoByHomeOrderNo(projectOrderId, billCode, null)
			.stream()
			.map(SubOrderBaseInfoDTO::getOrderNo)
			.collect(Collectors.toList());
	}

	/**
	 * 处理协同报价单与合同的解绑
	 */
	private void unbindCooperQuotationFromContract(Contract contract, String billCode, String projectOrderId, Long operatorUcid) {
		if (isContractInInvalidOrFinalStatus(contract)) {
			return;
		}

		// 查询合同关联的所有类型单据（bindType=null 查询所有类型）
		List<ContractQuotationRelation> allRelations = contractQuotationRelationService
			.getByContractCode(contract.getContractCode(), RelationStatusEnum.RELATED.getCode(), null);
		if (CollectionUtil.isEmpty(allRelations)) {
			return;
		}

		// 判断操作类型：仅绑定该报价单则作废合同，否则解除关联并撤回
		ContractRevocationAction action = determineRevocationActionForDirectBound(allRelations, billCode);

		List<String> subOrderNos = getSubOrderNosByBillCode(projectOrderId, billCode);
		executeRevocationAction(action, contract, billCode, subOrderNos, operatorUcid);
	}

	/**
	 * 处理 S 单与合同的解绑
	 * 协同报价单撤回时，如果该报价单未直接关联合同，可能是由于协同报价单已下单换成 S 单，
	 * 合同已由协同报价单换绑到 S 单。此时需要通过 S 单来撤回对应合同。
	 */
	private void unbindSubOrderFromContract(String projectOrderId, String billCode, Long operatorUcid) {
		List<String> subOrderNos = getSubOrderNosByBillCode(projectOrderId, billCode);

		if (CollectionUtil.isEmpty(subOrderNos)) {
			LOGGER.info("协同报价单 {} 未找到对应的 S 单，跳过 S 单撤回逻辑", billCode);
			return;
		}

		LOGGER.info("协同报价单 {} 对应的 S 单: {}", billCode, subOrderNos);

		// 查询这些 S 单是否关联合同（bindType=SUB_ORDER）
		List<ContractQuotationRelation> subOrderRelations = contractQuotationRelationService
			.getByBillCodesAndStatus(subOrderNos, RelationStatusEnum.RELATED.getCode(), BindTypeEnum.SUB_ORDER.getCode());

		if (CollectionUtil.isEmpty(subOrderRelations)) {
			LOGGER.info("协同报价单 {} 对应的 S 单未关联合同，跳过撤回逻辑", billCode);
			return;
		}

		// 按合同分组处理
		Map<String, List<ContractQuotationRelation>> contractRelationMap = subOrderRelations.stream()
			.collect(Collectors.groupingBy(ContractQuotationRelation::getContractCode));

		Set<String> toUnbindSubOrders = new HashSet<>(subOrderNos);

		for (Map.Entry<String, List<ContractQuotationRelation>> entry : contractRelationMap.entrySet()) {
			String contractCode = entry.getKey();
			Contract contract = contractService.getByContractCode(contractCode);

			if (contract == null || isContractInInvalidOrFinalStatus(contract)) {
				continue;
			}

			List<ContractQuotationRelation> currContractRelations = contractQuotationRelationService
				.getByContractCode(contractCode, RelationStatusEnum.RELATED.getCode(), null);

			if (CollectionUtil.isEmpty(currContractRelations)) {
				continue;
			}

			ContractRevocationAction action = determineRevocationActionForSubOrder(currContractRelations, toUnbindSubOrders);
			executeRevocationAction(action, contract, billCode, subOrderNos, operatorUcid);
		}
	}

	/**
	 * 判断直接绑定单据的合同应执行的操作类型（仅绑定该单据则作废合同，否则解除关联并撤回）
	 */
	private ContractRevocationAction determineRevocationActionForDirectBound(List<ContractQuotationRelation> allRelations, String billCode) {
		return (allRelations.size() == 1 && ObjectUtil.equal(allRelations.get(0).getBillCode(), billCode))
			? ContractRevocationAction.CANCEL_CONTRACT
			: ContractRevocationAction.UNBIND_AND_UNDO;
	}

	/**
	 * 判断通过 S 单绑定的合同应执行的操作类型
	 */
	private ContractRevocationAction determineRevocationActionForSubOrder(List<ContractQuotationRelation> currContractRelations, Set<String> toUnbindSubOrders) {
		// 判断合同是否绑定了报价单或变更单
		boolean hasBillOrChangeOrder = currContractRelations.stream()
			.anyMatch(r -> BindTypeEnum.BILL_CODE.getCode().equals(r.getBindType())
				|| BindTypeEnum.CHANGE_ORDER.getCode().equals(r.getBindType()));

		if (hasBillOrChangeOrder) {
			// 绑定了报价单或变更单 → 解除 S 单关联并撤回
			return ContractRevocationAction.UNBIND_AND_UNDO;
		}

		// 获取当前合同所绑定的 S 单
		Set<String> currContractSubOrders = currContractRelations.stream()
			.map(ContractQuotationRelation::getBillCode)
			.collect(Collectors.toSet());


		if (toUnbindSubOrders.containsAll(currContractSubOrders)) {
			// 如果当前合同绑定的 S 单，被包含在了要取消的 S 单中，则直接作废当前合同
			return ContractRevocationAction.CANCEL_CONTRACT;
		} else {
			// 合同绑定了其他 S 单 → 解除当前 S 单关联并撤回
			return ContractRevocationAction.UNBIND_AND_UNDO;
		}
	}

	/**
	 * 执行合同撤回操作
	 */
	private void executeRevocationAction(ContractRevocationAction action, Contract contract, String billCode, List<String> subOrderNos, Long operatorUcid) {
		switch (action) {
			case CANCEL_CONTRACT:
				LOGGER.info("作废合同 {}", contract.getContractCode());
				commonContractService.cancelCurrentContract(contract, operatorUcid, true);
				break;
			case UNBIND_AND_UNDO:
				LOGGER.info("解除合同 {} 关联并撤回", contract.getContractCode());
				// 同时解绑报价单号和 S 单号（如果存在绑定关系则解绑，不存在则无操作）
				List<String> billCodesToCancel = new ArrayList<>();
				billCodesToCancel.add(billCode);
				if (CollectionUtil.isNotEmpty(subOrderNos)) {
					billCodesToCancel.addAll(subOrderNos);
				}
				contractQuotationRelationService.cancelRelationsByBillCodes(contract.getContractCode(), billCodesToCancel);
				// 记录解绑日志
				contractBindLogService.recordUnbindLog(
					contract.getContractCode(),
					"个性化合同-解除关联并撤回",
					billCodesToCancel
				);
				undoContractIfNeeded(contract, operatorUcid);
				break;
			case SKIP:
			default:
				break;
		}
		// 清理正签草稿字段
		cleanFormalContractDraftFields(contract, billCode, subOrderNos);
	}

	/**
	 * 判断合同是否处于无效态、终态或已确认后申请用章状态
	 */
	private boolean isContractInInvalidOrFinalStatus(Contract contract) {
		return ContractStatusEnum.CANCEL.getCode().equals(contract.getStatus())
			|| ContractStatusEnum.SIGNED_STATUS_LIST.contains(contract.getStatus())
			|| (ContractStatusEnum.PENDING_USER_SIGN.getCode().equals(contract.getStatus()) && CommonEnum.YES.getCode().equals(contract.getUserConfirmStatus()));
	}

	/**
	 * 如果合同状态允许，回退合同状态到草稿
	 */
	private void undoContractIfNeeded(Contract contract, Long operatorUcid) {
		if (canUndoContract(contract)) {
			homeAndPcCommonService.undoContract(contract, operatorUcid);
		}
	}

	/**
	 * 判断合同是否可以回退到草稿
	 */
	private boolean canUndoContract(Contract contract) {
		return !ContractStatusEnum.DRAFT.getCode().equals(contract.getStatus())
			&& !isContractInInvalidOrFinalStatus(contract);
	}

	/**
	 * 清理正签草稿字段（移除协同报价单号、S 单号）
	 */
	private void cleanFormalContractDraftFields(Contract contract, String billCode, List<String> subOrderNos) {
		ContractRelation formalContract = contractRelationService.getByRelateContractCode(contract.getContractCode());
		if (formalContract != null) {
			// 从正签草稿中移除协同报价单
			contractFieldHandler.removeBillCodeFromContractField(formalContract, billCode);
			// 从正签草稿中移除 S 单号
			contractFieldHandler.removeSubOrderNoFromContractField(formalContract, subOrderNos);
		}
	}

}

