@Slf4j
public abstract class AbstractContractSigningSource implements ContractSigningSource{

	@Resource
	@Lazy
	private HomeOrderDataConversionService homeOrderDataConversionService;

	@Resource
	private ContractQuotationRelationService contractQuotationRelationService;

	@Resource
	private AtomDrawingRpc atomDrawingRpc;

	@Resource
	private ContractService contractService;

	@Resource
	private SubOrderFeignService subOrderFeignService;

	@Override
	public List<ContractSourceDataBO.PersonalContractData> queryPersonalQuoteInfo(BindOrderInfo bindOrderInfo) {
		// 1. 构建参数
		PersonalContractDataParam personalContractDataParam = buildParam(bindOrderInfo);
		// 2. 执行查询
		ContractSourceDataBO contractSourceDataBO = QueryHelper.unwrap(p -> homeOrderDataConversionService.contractPersonalDataV2(p), personalContractDataParam, "contractPersonalDataV2");
		List<ContractSourceDataBO.PersonalContractData> personalContractDataList = contractSourceDataBO.getPersonalContractDataList();
		if (CollectionUtils.isEmpty(personalContractDataList)) {
			throw new NrsBusinessException(ResultCodeEnum.ERROR_BUSINESS.getCode(), "个性化合同报价信息为空");
		}
		// 3. 过滤出所需主体的个性化报价数据
		personalContractDataList = filterByCompanyCode(bindOrderInfo, personalContractDataList);
		LOGGER.info("contractPersonalDataV2, homeOrderNo: {}, personalContractDataList: {}", bindOrderInfo.getProjectOrderId(), personalContractDataList);
		return personalContractDataList;
	}

	@Override
	public List<String> buildPersonalDrawingImgList(BindOrderInfo bindOrderInfo) {
		LOGGER.info("buildPersonalDrawingImgList 入参: {}", JSON.toJSONString(bindOrderInfo));
		// 1. 获取个性化图纸
		DrawingDTO.DeliverDrawingDTO deliverDrawingDTO = buildPersonalDrawing(bindOrderInfo, null, Boolean.FALSE);

		// 2. 筛选个性化图纸返回
		return Optional.ofNullable(deliverDrawingDTO).map(DrawingDTO.DeliverDrawingDTO::getDrawingDetailDTOList)
			.orElse(Collections.emptyList())
			.stream()
			.flatMap(drawingDetail -> drawingDetail.previewPathList().stream())
			.collect(Collectors.toList());
	}

	@Override
	public DrawingDTO.DeliverDrawingDTO buildPersonalDrawing(BindOrderInfo bindOrderInfo, Boolean softConfigList, Boolean needMergePdf) {
		// 1. 根据单据号查询商品行数据
		List<String> productItemCodes = buildProductItemCodes(bindOrderInfo);
		LOGGER.info("个性化图纸查询, 原始单据号: {}, 商品唯一键: {}", JSON.toJSONString(bindOrderInfo.getBindOrderNoList()), JSON.toJSONString(productItemCodes));
		// 2. 构造查询图纸参数
		DrawingParams.DrawingQuery drawingQueryParam = buildDrawingQuery(bindOrderInfo.getProjectOrderId(), bindOrderInfo.getChangeOrderId(), productItemCodes, softConfigList, needMergePdf);
		LOGGER.info("个性化图纸查询, projectOrderId: {}, drawingQueryParam: {}", bindOrderInfo.getProjectOrderId(), JSON.toJSONString(drawingQueryParam));

		// 3. 商品行数据查询图纸信息
		DrawingDTO.DeliverDrawingDTO deliverDrawingDTO = atomDrawingRpc.listDrawingsRpc(drawingQueryParam);

		if (deliverDrawingDTO == null || CollectionUtils.isEmpty(deliverDrawingDTO.getDrawingDetailDTOList())) {
			return DrawingDTO.DeliverDrawingDTO.builder().drawingDetailDTOList(Collections.emptyList()).build();
		}

		// 4. 筛选个性化图纸
		List<DrawingDTO.DrawingDetailDTO> drawingDetailDTOS = deliverDrawingDTO.getDrawingDetailDTOList()
			.stream()
			.filter(drawingDetail -> Objects.equals(PlanAttachment.个性化图纸, drawingDetail.getBillType()))
			.filter(drawingDetail -> DrawingEnum.ConstructionFileExtensionEnum.PDF.getCode().equals(drawingDetail.getExtensionType()))
			.collect(Collectors.toList());

		LOGGER.info("个性化图纸查询结束, projectOrderId: {}, drawingDetailDTOS: {}", bindOrderInfo.getProjectOrderId(), JSON.toJSONString(drawingDetailDTOS));

		deliverDrawingDTO.setDrawingDetailDTOList(drawingDetailDTOS);
		return deliverDrawingDTO;
	}

	protected abstract DrawingParams.DrawingQuery buildDrawingQuery(String projectOrderId, String changeOrderId, List<String> productItemCodes, Boolean softConfigList, Boolean needMergePdf);

	/**
	 * 获取单据号对应的商品唯一键
	 */
	protected abstract List<String> buildProductItemCodes(BindOrderInfo bindOrderInfo);

	/**
	 * 构建查询参数
	 */
	protected abstract PersonalContractDataParam buildParam(BindOrderInfo bindOrderInfo);

	/**
	 * 含义：根据要绑定的[单据号+主体]过滤所需的个性化报价数据
	 * personalContractDataList 入参说明：根据单号查询的个性化数据，报价单/变更单会存在多主体，因此可能返回不需要的主体的数据，需要根据[单据号+主体]再进行一次筛选。
	 *
	 * 过滤逻辑：
	 * - 报价单/变更单：根据单据号+主体过滤。
	 * - S 单：不需要过滤。（S 单只有单个主体）
	 */
	protected abstract List<ContractSourceDataBO.PersonalContractData> filterByCompanyCode(BindOrderInfo bindOrderInfo, List<ContractSourceDataBO.PersonalContractData> personalContractDataList);

	/**
	 * 聚合类目，作为商品信息 goodsInfo 带入到销售合同
	 */
	protected String mergeCategoryNames(Set<String> categoryNames) {
		int i = 0;
		StringBuilder goodsInfo = new StringBuilder();
		for (String distinctCategoryName : categoryNames) {
			if (i >= 3) {
				break;
			}
			if (i == 0) {
				goodsInfo.append(distinctCategoryName);
			} else if (i == 1) {
				goodsInfo.append(",").append(distinctCategoryName);
			} else if (i == 2) {
				goodsInfo.append("等");
			}
			i++;
		}
		return goodsInfo.toString();
	}

	/**
	 * 获取已绑定合同的单据号
	 * isEdit = true: 编辑合同场景，则认为已绑定草稿合同的单据仍然是有效单据。
	 * isEdit= false：非编辑合同场景（弹窗场景），则认为已绑定草稿合同的单据为无效单据
	 */
	protected Set<String> getHasBoundOrderNos(List<String> subOrderNos, Integer bindType, boolean isEdit) {
		if (CollectionUtils.isEmpty(subOrderNos)) {
			return Collections.emptySet();
		}
		List<ContractQuotationRelation> relations = contractQuotationRelationService.getByBillCodesAndStatus(subOrderNos, RelationStatusEnum.RELATED.getCode(), bindType);
		if (CollectionUtils.isEmpty(relations)) {
			return Collections.emptySet();
		}
		Set<String> res = new HashSet<>();
		List<Integer> validContractStatus;
		if (isEdit) {
			validContractStatus = ContractStatusEnum.validStatusWithoutDraft;
		} else {
			validContractStatus = ContractStatusEnum.allValidStatus;
		}
		// 过滤掉草稿合同的关联关系
		for (ContractQuotationRelation relation : relations) {
			Contract contract = contractService.getByContractCode(relation.getContractCode());
			if (validContractStatus.contains(contract.getStatus())) {
				res.add(relation.getBillCode());
			}
		}
		LOGGER.info("已绑定合同的 S 单: {}, isEdit: {}", JSON.toJSONString(res), isEdit);
		return res;
	}

	protected Map<String, String> buildPackageCodeMap(List<String> subOrderNos) {
		return subOrderFeignService.batchQuerySubOrderByNo(subOrderNos).stream()
			.filter(Objects::nonNull)
			.filter(order -> CollectionUtils.isNotEmpty(order.getSubOrderItems()))
			.collect(Collectors.toMap(
				SubOrderDto::getOrderNo,
				order -> order.getSubOrderItems().get(0).getPackageInstanceCode(),
				(v1, v2) -> v1
			));
	}

	protected Set<String> getPackageCodesByOrderNos(Set<String> orderNos) {
		return buildPackageCodeMap(new ArrayList<>(orderNos)).values().stream()
			.filter(StringUtils::isNotBlank)
			.collect(Collectors.toSet());
	}


	/**
	 * 判断产品的 purchaseType 是否属于 C 承担
	 */
	protected boolean isCPart(Integer purchaseType) {
		if (purchaseType == null) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "报价单中存在未设置purchaseType，无法判断是否为C部分报价");
		}
		return purchaseType.equals(PurchaseTypeEnum.客户承担成本.getCode());
	}

	/**
	 * 判断单个个性化报价是否包含 B 方承担部分
	 */
	protected boolean isBPart(Integer purchaseType) {
		if (purchaseType == null) {
			throw new UtopiaBussinessException(ResultCodeEnum.ERROR_BUSINESS, "报价单中存在未设置purchaseType，无法判断是否为B部分报价");
		}
		return Arrays.asList(PurchaseTypeEnum.开发商承担成本.getCode(), PurchaseTypeEnum.开发商客户混合承担成本.getCode()).contains(purchaseType);
	}
}

