@Service
@Slf4j
public class BillSigningSourceStrategy extends AbstractContractSigningSource {


	@Resource
	private OrderStandardQueryRpc orderStandardQueryRpc;

	@Resource
	private HomeOrderDataConversionService homeOrderDataConversionService;

	@Resource
	private CommonBusinessService commonBusinessService;

	@Resource
	private ContractDependentDataService contractDependentDataService;

	@Resource
	private AtomBudgetRpc atomBudgetRpc;

	@Resource
	private ProductQueryService productQueryService;

	@Override
	public Integer bindType() {
		return BindTypeEnum.BILL_CODE.getCode();
	}

	@Override
	public boolean hasInvalidStatusOrders(BindOrderInfo bindOrderInfo) {
		//校验报价单是否存在
		BudgetParams.QueryBillsCondition budgetParams = BudgetParams.QueryBillsCondition.builder()
			.projectOrderId(bindOrderInfo.getProjectOrderId())
			.billCodes(bindOrderInfo.getBindOrderNoList())
			.build();
		List<com.ke.utopia.atom.api.budget.dto.BudgetBillDTO.BillDTO> billDTOS = atomBudgetRpc.queryBillsByCondition(budgetParams);
		if (CollectionUtil.isEmpty(billDTOS)) {
			return true;
		}
		for (com.ke.utopia.atom.api.budget.dto.BudgetBillDTO.BillDTO billDTO : billDTOS) {
			//所选组合单关联报价单状态无法发起签约，请重新选择
			if (GeneralBillStatusEnum.IN_ADJUST.getCode().equals(billDTO.getStatus())
				|| GeneralBillStatusEnum.DELETED.getCode().equals(billDTO.getStatus())
				|| GeneralBillStatusEnum.CANCELED.getCode().equals(billDTO.getStatus())) {
				return true;
			}
		}
		return false;
	}

	@Override
	public Map<String, String> buildGoodsInfo(BindOrderInfo bindOrderInfo) {

		/**
		 * 构建报价单的 goodsInfo
		 * billCode -> goodsInfo
		 */
		List<String> billCodeList = bindOrderInfo.getBindOrderNoList();
		String projectOrderId = bindOrderInfo.getProjectOrderId();

		Map<String, String> result = new HashMap<>();
		billCodeList.forEach(
			billCode -> {
				Set<SkuProductDTO> skuProducts = getSkuProductsByBillCode(projectOrderId, Collections.singletonList(billCode));
				// 遍历商品，将内控类目合并生成 goodsInfo 合并后统一提取类目名
				Set<String> categoryNames = skuProducts.stream()
					.map(SkuProductDTO::getSkuCategoryName)
					.collect(Collectors.toSet());
				result.put(billCode, mergeCategoryNames(categoryNames));
			}
		);
		return result;
	}

	/**
	 * 根据主单号 + 报价单号获取 sku 商品集合
	 */
	private Set<SkuProductDTO> getSkuProductsByBillCode(String projectOrderId, List<String> billCodeList) {
		List<QuotationProductDTO> quotationProductDTOS = productQueryService.getQuotationProductDTOS(projectOrderId, billCodeList);
		return quotationProductDTOS.stream().map(QuotationProductDTO::getSkuProduct).filter(Objects::nonNull).collect(Collectors.toSet());
	}

	/**
	 * 获取可签约的报价单据（基础报价内的个性化报价单）
	 */
	@Override
	public List<SignableOrderInfo> buildSignableOrderInfos(String projectOrderId) {
		List<SignableOrderInfo> result = new ArrayList<>();

		//获取正签报价
		ContractSourceDataBO contractSourceDataBO = QueryHelper.unwrap((p1, p2) -> homeOrderDataConversionService.contractSourceDateNoThrow(p1, p2), projectOrderId, "", "contractSourceDateNoThrow");

		if (ObjectUtil.isNull(contractSourceDataBO.getPlanAllDTO())) {
			return result;
		}

		// 如果无需处理，则提前返回
		if (!shouldProcessPersonalContractData(projectOrderId, contractSourceDataBO)) {
			return result;
		}

		// 获取正签报价里的个性化数据
		List<ContractSourceDataBO.PersonalContractData> personalContractDataList = contractSourceDataBO.getPersonalContractDataList();
		if (CollectionUtils.isEmpty(personalContractDataList)) {
			return result;
		}

		// 构建可签约的报价单据
		for (ContractSourceDataBO.PersonalContractData personalContractData : personalContractDataList) {
			List<String> billCodeList = Collections.singletonList(personalContractData.getBillCode());
			BindOrderInfo bindOrderInfo = BindOrderInfo.convertWithoutCompanyCode(projectOrderId, null, billCodeList, null);
			Map<String, String> goodsInfoMapByOrderNo = buildGoodsInfo(bindOrderInfo);
			// 构建可签约的报价单据
			SignableOrderInfo signableQuotationOrderInfo = SignableOrderInfo.buildSignableBillOrderInfo(personalContractData, SignableOrderInfo.PrerequisitesData.builder().goodsInfoByOrderNo(goodsInfoMapByOrderNo).build());
			result.add(signableQuotationOrderInfo);
		}
		return result;
	}

	@Override
	public boolean checkPersonalCanCreate(String projectOrderId) {
		return false;
	}

	@Override
	public boolean hasCPart(BindOrderInfo bindOrderInfo) {
		List<QuotationProductDTO> quotationProductDTOS = productQueryService.getQuotationProductDTOS(bindOrderInfo.getProjectOrderId(), bindOrderInfo.getBindOrderNoList());
		if (CollectionUtils.isEmpty(quotationProductDTOS)) {
			return false;
		}
		return quotationProductDTOS.stream()
				.anyMatch(p -> isCPart(p.getPurchaseType()));
	}

	@Override
	public boolean hasBPart(BindOrderInfo bindOrderInfo) {
		List<QuotationProductDTO> quotationProductDTOS = productQueryService.getQuotationProductDTOS(bindOrderInfo.getProjectOrderId(), bindOrderInfo.getBindOrderNoList());
		if (CollectionUtils.isEmpty(quotationProductDTOS)) {
			return false;
		}
		return quotationProductDTOS.stream().anyMatch(p -> isBPart(p.getPurchaseType()));
	}

	@Override
	protected DrawingParams.DrawingQuery buildDrawingQuery(String projectOrderId, String changeOrderId, List<String> productItemCodes, Boolean softConfigList, Boolean needMergePdf) {
		return DrawingParams.DrawingQuery.builder()
			.projectOrderId(projectOrderId)
			.softConfigList(softConfigList)
			.needMergePdf(needMergePdf)
			.productItemCodes(productItemCodes).build();
	}

	@Override
	protected List<String> buildProductItemCodes(BindOrderInfo bindOrderInfo) {
		Set<SkuProductDTO> skuProducts = getSkuProductsByBillCode(bindOrderInfo.getProjectOrderId(), bindOrderInfo.getBindOrderNoList());
		return skuProducts.stream().map(SkuProductDTO::getProductItemCode).collect(Collectors.toList());
	}

	@Override
	public PersonalContractDataParam buildParam(BindOrderInfo bindOrderInfo) {
		return PersonalContractDataParam.builder()
			.projectOrderId(bindOrderInfo.getProjectOrderId())
			.billCodeList(bindOrderInfo.getBindOrderNoList())
			.build();
	}

	@Override
	protected List<ContractSourceDataBO.PersonalContractData> filterByCompanyCode(BindOrderInfo bindOrderInfo, List<ContractSourceDataBO.PersonalContractData> personalContractDataList) {
		Set<String> targetCodeWithCompany = bindOrderInfo.getBindOrderNosWithCompany();
		return personalContractDataList.stream()
			.filter(item -> targetCodeWithCompany.contains(item.getBillCode() + "_" + item.getOrganizationCode()))
			.collect(Collectors.toList());
	}

	/**
	 * 是否处理个性化报价数据
	 */
	private boolean shouldProcessPersonalContractData(String projectOrderId, ContractSourceDataBO contractSourceDataBO) {
		Byte businessType = commonBusinessService.getBusinessType(projectOrderId);
		if (BusinessTypeEnum.REFORM_ALL.getCode().equals(businessType) && CollectionUtils.isNotEmpty(contractSourceDataBO.getPersonalContractDataList())) {
			return true;
		}

		if (BusinessTypeEnum.HOUSE_CERTIFICATE.getCode().equals(businessType) && CollectionUtils.isNotEmpty(contractSourceDataBO.getPersonalContractDataList())) {
			return true;
		}
		return false;
	}
}

