@Service
@Slf4j
public class SubOrderSigningSourceStrategy extends AbstractContractSigningSource {

	@Resource
	private OrderQueryApi orderQueryApi;

	@Resource
	private SubOrderFeignService subOrderFeignService;

	@Resource
	private ContractQuotationRelationService contractQuotationRelationService;

	@Resource
	private MdmRpc mdmRpc;
    @Resource
    private PackageQueryFeignService packageQueryFeignService;

	@Resource
	private CommonBusinessService commonBusinessService;

	@Override
	public Integer bindType() {
		return BindTypeEnum.SUB_ORDER.getCode();
	}

	@Override
	public boolean hasInvalidStatusOrders(BindOrderInfo bindOrderInfo) {
		List<String> subOrderNos = bindOrderInfo.getBindOrderNoList().stream().distinct().collect(Collectors.toList());
		List<SubOrderDto> subOrders = subOrderFeignService.batchQuerySubOrderByNo(subOrderNos);

		// 校验个数
		if (subOrderNos.size() != subOrders.size()) {
			return true;
		}

		// 校验状态
		Optional<SubOrderDto> invalidSubOrder = subOrders.stream().filter(subOrder -> SubOrderFeignService.invalidStatus.contains(subOrder.getStatus())).findFirst();

		return invalidSubOrder.isPresent();
	}

	@Override
	public Map<String, String> buildGoodsInfo(BindOrderInfo bindOrderInfo) {
		List<String> subOrderNos = bindOrderInfo.getBindOrderNoList();
		Map<String, String> goodsInfoMapByOrderNo = new HashMap<>();
		if (CollectionUtils.isEmpty(subOrderNos)) {
			return goodsInfoMapByOrderNo;
		}
		List<SubOrderDto> subOrders = subOrderFeignService.batchQuerySubOrderByNo(subOrderNos);
		subOrders.forEach(subOrderDto -> {
			Set<String> categoryNames = new HashSet<>();
			List<SubOrderItemDto> subOrderItems = subOrderDto.getSubOrderItems();
			subOrderItems.forEach(
				item -> {
					String categoryName = StringUtils.isEmpty(item.getFrontCategoryName()) ? item.getBackCategoryName() : item.getFrontCategoryName();
					if (!StringUtils.isEmpty(categoryName) && categoryName.length() > 50) {
						// db总长 128，最多展示三个的拼接
						categoryName = categoryName.substring(0, 49) + "...";
					}
					categoryNames.add(categoryName);
				}
			);
			String goodsInfo = mergeCategoryNames(categoryNames);
			goodsInfoMapByOrderNo.put(subOrderDto.getOrderNo(), goodsInfo);
		});
		return goodsInfoMapByOrderNo;
	}
	/**
	 * 通过主订单获取可签约的 S 单据
	 */
	@Override
	public List<SignableOrderInfo> buildSignableOrderInfos(String projectOrderId) {
		return buildSignableOrderInfos(projectOrderId, false);
	}

	/**
	 * 获取已绑定合同的子单
	 * isEdit: 是否为编辑合同场景
