	/**
	 * 获取可签约的 S 单
	 */
	private List<SubOrderBaseInfoDTO> getSignableSubOrderNos(List<SubOrderBaseInfoDTO> subOrderInfos, boolean isEdit) {
		if (CollectionUtils.isEmpty(subOrderInfos)) {
			return Collections.emptyList();
		}
		List<String> subOrderNos = subOrderInfos.stream().map(SubOrderBaseInfoDTO::getOrderNo).collect(Collectors.toList());
		// 获取变更中的 S 单
		Set<String> changingSubOrderNos = subOrderFeignService.getChangingSubOrderNos(subOrderNos);
		// 获取已绑定合同的 S 单
		Set<String> boundSubOrderNos = getHasBoundOrderNos(subOrderNos, bindType(), isEdit);
		// 获取套餐已签约的 S 单
		Set<String> packageSignedSubOrderNos = getPackageSignedSubOrderNos(subOrderNos, boundSubOrderNos);
		// 过滤掉变更中 & 已绑定合同的 S 单 & 套餐未签约的 S 单
		return subOrderInfos.stream().filter(subOrderInfo ->
			!changingSubOrderNos.contains(subOrderInfo.getOrderNo())
			&& !boundSubOrderNos.contains(subOrderInfo.getOrderNo())
			&& !packageSignedSubOrderNos.contains(subOrderInfo.getOrderNo())
		).collect(Collectors.toList());
	}

	/**
	 * 获取套餐已签约的 S 单
	 */
	protected Set<String> getPackageSignedSubOrderNos(List<String> subOrderNos, Set<String> boundSubOrderNos) {
		// 1. 获取已绑定合同的子单套餐
		Set<String> boundPackageCodes = getPackageCodesByOrderNos(boundSubOrderNos);

		// 2. 找出同套餐的子单号
		Map<String, String> packageCodeByOrderNo = buildPackageCodeMap(subOrderNos);
		Set<String> res = subOrderNos.stream()
			.filter(orderNo -> {
				String packageCode = packageCodeByOrderNo.get(orderNo);
				return StringUtils.isNotBlank(packageCode) && boundPackageCodes.contains(packageCode);
			})
			.collect(Collectors.toSet());
		LOGGER.info("套餐已签约的 S 单: {}, 已签约的套餐: {}", JSON.toJSONString(res), JSON.toJSONString(boundPackageCodes));
		return res;
	}


	/**
	 * 构建 SignableOrderInfo 所需的依赖数据
	 * - companyName：公司主体名称
	 * - goodsInfo：商品信息
	 */
	private SignableOrderInfo.PrerequisitesData buildSignableOrderInfoPreData(String projectOrderId, List<SubOrderBaseInfoDTO> signableSubOrderBaseInfos) {
		// 获取公司主体的中文名
		List<String> companyCodes = signableSubOrderBaseInfos.stream().map(SubOrderBaseInfoDTO::getMdmCode).collect(Collectors.toList());
		Map<String, MdmDTO> companyInfoMapByCompanyCode = mdmRpc.obtainMdmMapByMdmCodes(companyCodes);

		// 获取 goodsInfo
		List<String> subOrderNos = signableSubOrderBaseInfos.stream().map(SubOrderBaseInfoDTO::getOrderNo).collect(Collectors.toList());
		BindOrderInfo bindOrderInfo = BindOrderInfo.convertWithoutCompanyCode(projectOrderId, subOrderNos, null, null);
		Map<String, String> goodsInfoMapByOrderNo = buildGoodsInfo(bindOrderInfo);

		// 获取套餐的中文名称
		Map<String, String> packageNameByOrderNo = getPackageNameByOrderNo(projectOrderId, subOrderNos);

		// 是否是团装2.5
		Boolean isProcessV25Group = Optional.of(commonBusinessService.isPROCESS_V2_5_GROUP(projectOrderId)).orElse(Boolean.FALSE);

		// 构造 subOrderInfo 的 goodsInfo
		return SignableOrderInfo.PrerequisitesData.builder()
			.companyInfoMapByCompanyCode(companyInfoMapByCompanyCode)
			.goodsInfoByOrderNo(goodsInfoMapByOrderNo)
			.packageNameByOrderNo(packageNameByOrderNo)
			.groupV25(isProcessV25Group)
			.build();
	}

	/**
	 * 套餐 Code 位于子单下的商品 Item 属性内部：（同一个子单下的所有商品都是同一个套餐）
	 * （1）先构建 packageInstanceCode -> packageInstanceName 的映射
	 * （2）再构建 subOrderNo -> packageInstanceName 的映射
	 */
	private Map<String, String> getPackageNameByOrderNo(String projectOrderId, List<String> subOrderNos) {
		if (CollectionUtils.isEmpty(subOrderNos)) {
			return Collections.emptyMap();
		}
		List<SubOrderDto> subOrderDtos = subOrderFeignService.batchQuerySubOrderByNo(subOrderNos).stream()
				.filter(Objects::nonNull)
				.filter(order -> CollectionUtils.isNotEmpty(order.getSubOrderItems()))
				.collect(Collectors.toList());

		List<String> packageInstanceCodes = subOrderDtos.stream()
				.flatMap(order -> order.getSubOrderItems().stream())
				.map(SubOrderItemDto::getPackageInstanceCode)
				.filter(StringUtils::isNotBlank)
				.distinct()
				.collect(Collectors.toList());

		if (CollectionUtils.isEmpty(packageInstanceCodes)) {
			return Collections.emptyMap();
		}

		Map<String, PackageDTO> packageByCode = packageQueryFeignService.batchQueryPackageInfo(projectOrderId, packageInstanceCodes);

		return subOrderDtos.stream().collect(
				Collectors.toMap(
					SubOrderDto::getOrderNo, // key：子单号
					subOrderDto -> Optional.ofNullable(packageByCode.get(subOrderDto.getSubOrderItems().get(0).getPackageInstanceCode())).map(PackageDTO::getPackageName).orElse(""), // value：套餐名称
					(existing, replacement) -> existing // 重复 key 保留第一个
			));
	}


}

